/* Route geometry shared by the simulation, renderer and authoring tools.

   A path is an array of control points [x, y, w, lane] in plate design pixels
   (841 × 1870):
     x, y  foot point of the lane centre (bottom-centre sprite anchor)
     w     the racer's on-screen sprite width at that point (depth scale)
     lane  horizontal distance in plate pixels between adjacent lanes (0 = single file)

   Positions are smoothed with a Catmull-Rom spline. The path parameter f (0..1)
   is proportional to distance measured in racer widths (∫ |dp| / w), so a racer
   moving at a constant world speed covers equal f per second whether the path is
   near the camera or far away. Fractions in plate data always use this metric. */
(function (WW) {
  'use strict';
  const SUB = 12;
  const cache = new WeakMap();

  function catmull(p0, p1, p2, p3, t) {
    const t2 = t * t, t3 = t2 * t;
    return 0.5 * ((2 * p1) + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 + (-p0 + 3 * p1 - 3 * p2 + p3) * t3);
  }

  function prepare(points) {
    let prepared = cache.get(points);
    if (prepared) return prepared;
    if (!points || points.length < 2) throw new Error('A path needs at least two points');
    const n = points.length, dense = [];
    const at = function (i) { return points[Math.max(0, Math.min(n - 1, i))]; };
    for (let i = 0; i < n - 1; i++) {
      const p0 = at(i - 1), p1 = at(i), p2 = at(i + 1), p3 = at(i + 2);
      for (let k = 0; k < SUB; k++) {
        const t = k / SUB;
        dense.push([
          catmull(p0[0], p1[0], p2[0], p3[0], t),
          catmull(p0[1], p1[1], p2[1], p3[1], t),
          p1[2] + (p2[2] - p1[2]) * t,
          (p1[3] || 0) + ((p2[3] || 0) - (p1[3] || 0)) * t
        ]);
      }
    }
    const last = points[n - 1];
    dense.push([last[0], last[1], last[2], last[3] || 0]);
    const cum = [0];
    for (let i = 1; i < dense.length; i++) {
      const a = dense[i - 1], b = dense[i];
      const len = Math.hypot(b[0] - a[0], b[1] - a[1]) / Math.max(1, (a[2] + b[2]) / 2);
      cum.push(cum[i - 1] + len);
    }
    const total = cum[cum.length - 1] || 1;
    prepared = { dense: dense, cum: cum.map(function (c) { return c / total; }), widths: total };
    cache.set(points, prepared);
    return prepared;
  }

  /* Returns {x, y, w, lane, tx, ty, f}; (tx, ty) is the unit direction of travel. */
  function sample(points, f) {
    const p = prepare(points);
    f = f < 0 ? 0 : f > 1 ? 1 : f;
    const cum = p.cum, d = p.dense;
    let lo = 0, hi = cum.length - 1;
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1;
      if (cum[mid] <= f) lo = mid; else hi = mid;
    }
    const span = cum[hi] - cum[lo] || 1;
    const t = (f - cum[lo]) / span;
    const a = d[lo], b = d[hi];
    let tx = b[0] - a[0], ty = b[1] - a[1];
    const len = Math.hypot(tx, ty) || 1;
    return {
      x: a[0] + (b[0] - a[0]) * t,
      y: a[1] + (b[1] - a[1]) * t,
      w: a[2] + (b[2] - a[2]) * t,
      lane: a[3] + (b[3] - a[3]) * t,
      tx: tx / len, ty: ty / len, f: f
    };
  }

  /* Path fraction of the point on the path closest to (x, y). */
  function project(points, x, y) {
    const p = prepare(points);
    let best = 0, bestD = Infinity;
    for (let i = 0; i < p.dense.length; i++) {
      const q = p.dense[i];
      const d = (q[0] - x) * (q[0] - x) + (q[1] - y) * (q[1] - y);
      if (d < bestD) { bestD = d; best = i; }
    }
    return p.cum[best];
  }

  /* Foot point for a racer at fraction f, lane value laneX (-1..1, continuous)
     and jump height fraction jumpH (0..1). Lanes offset horizontally. */
  function racerPoint(points, f, laneX, jumpH) {
    const s = sample(points, f);
    return {
      x: s.x + (laneX || 0) * s.lane,
      y: s.y - (jumpH || 0) * s.w * 0.42,
      groundY: s.y,
      w: s.w, tx: s.tx, ty: s.ty, f: s.f
    };
  }

  /* Length of the path in racer widths; useful when choosing segment lengths. */
  function widths(points) { return prepare(points).widths; }

  WW.path = { prepare: prepare, sample: sample, project: project, racerPoint: racerPoint, widths: widths };
})(globalThis.WW = globalThis.WW || {});

13:Keep the magical suspended loom city: warm honey-colored wooden towers, tall hanging teal floral tapestries, coral and teal carpet ribbons, plum tassels, gold braided borders, glowing lanterns, clouds, waterfalls and the enormous flower gate. Raised embroidered flowers, chunky crochet and stitched edges create the rich handmade surface. The mood is cheerful, friendly and polished, with depth and detail that still let the player see the route.
15:Purl remains coral-red with one curled top tuft. Loop remains teal with two curled loops. Use short plush limbs and woven brown soles. Rear sprites are for gameplay; front poses belong in intentional menu/result moments, not running backward toward the viewer. Snagling stays a little plum tangle with a mischievous stitched expression. The butterfly is coral and gold embroidered fabric, emerging from a matching outline on the teal tapestry.
28:| `06-butterfly.png` | Tall teal floral tapestry on the left; matching butterfly outline and stitch fitting; coral/gold butterfly carrying gold spool to connected carpet terrace; Purl approaching from below; Loop on the right. |
29:| `07-finish.png` | Huge illuminated embroidered flower gate in its wooden loom ring; continuous approach/finish terrace; rear-view racers; celebratory petals; true rank and replay action. |
31:Show intermediate travel using the same tower scale, carpet edge treatment and recurring landmarks. Do not turn these into disconnected teleporting rooms. Both the ribbon and shortcut must visibly attach to a reachable surface. The three-tassel platform and butterfly collection area also require a physically continuous approach.
35:Use portrait framing behind and slightly above Purl. His back faces the viewer and he travels into the world. During normal play his feet generally sit near 76–80% of the action image height, with the complete body and tuft visible. Scene 07 reframes both racers to show the gate. Match the reference's individual composition instead of forcing identical screen coordinates for every scene.
39:Organize distant city/sky, middle towers and carpets, moving characters/props, foreground occluders and interface as distinct rendering layers. Use contact shadows and stable feet anchors. Character animation needs alternating steps and intentional poses; bobbing a single still frame is not a production running cycle. Tapestry butterflies need a flap/emergence sequence; an independent cutout alone is not the entire effect.
59:The kit carries the existing character, enemy, props, interaction and UI atlases plus revised feature art. Some retained poses or props support authoring but are not a requirement to reintroduce old mechanics. Use the new ribbon/shortcut/tassel/butterfly sequence as the design source. Keep original assets intact and put resized/compressed runtime derivatives in separate outputs.
#!/usr/bin/env python3
"""Draw a plate's authored route data over the clean plate for visual checking.

  python3 tools/plate-overlay.py p01 out.png [--scale 0.6] [--approved] [--clean]

Draws Purl's three lanes (centre solid, sides dashed), Purl sprites at the route
start, at every event and at the exit (scaled by the path's w), Loop's route and
sprites, event markers with labels, the stitch tap target, feature geometry
(ribbon/shortcut bands, tassels, butterfly flight, Snagling, gate arch) and the
occluder polygons. --approved uses the approved screenshot as the backdrop
(useful for matching scale/position); --clean draws only sprites (no lines).
Geometry is evaluated by game/src/core/path.js through Node, so the overlay is
exactly what the game uses.
"""
import argparse
import json
import os
import subprocess

from PIL import Image, ImageDraw

REPO = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
KIT = os.path.join(REPO, 'kit', 'Wishweave-Level1-Complete-Visual-Kit')

NODE = r"""
const path=require('path'); const R=process.argv[1]; const id=process.argv[2];
for (const f of ['core/ww.js','core/path.js','data/asset-data.js','data/plates/'+id+'.js']) require(path.join(R,'game/src',f));
const P=WW.PLATES[id]; const out={plate:P, purl:{}, loop:{}};
const S=(pts,f,l)=>WW.path.racerPoint(pts,f,l||0,0);
const dense=(pts,lane)=>{const a=[];for(let i=0;i<=200;i++)a.push(S(pts,i/200,lane));return a;};
out.purl.lanes=[-1,0,1].map(l=>dense(P.purl.path,l));
const fs=new Set([0,1]); for(const e of P.purl.events||[]) if(typeof e.f==='number') fs.add(e.f);
out.purl.samples=[...fs].sort((a,b)=>a-b).map(f=>S(P.purl.path,f,0));
if(P.loop&&P.loop.path){ out.loop.line=dense(P.loop.path,0);
  const lf=new Set([0,0.5,1]); for(const e of P.loop.events||[]) if(typeof e.f==='number') lf.add(e.f);
  out.loop.samples=[...lf].sort((a,b)=>a-b).map(f=>S(P.loop.path,f,0)); }
out.events=(P.purl.events||[]).filter(e=>typeof e.f==='number').map(e=>({e, p:S(P.purl.path,e.f,e.lane||0)}));
out.loopEvents=((P.loop&&P.loop.events)||[]).filter(e=>typeof e.f==='number').map(e=>({e, p:S(P.loop.path,e.f,0)}));
out.frames=WW.ASSETS.frames; out.images=WW.ASSETS.images;
console.log(JSON.stringify(out));
"""

APPROVED = {'p01': '01-ribbon', 'p02': '02-shortcut', 'p03': '03-tassels', 'p04': '04-snagged',
            'p06': '06-butterfly', 'p07': '07-finish'}


def load(pid):
    res = subprocess.run(['node', '-e', NODE, REPO, pid], capture_output=True, text=True, check=True)
    return json.loads(res.stdout)


def sprite(data, cache, name, width):
    fr = data['frames'][name]
    key = fr['img']
    if key not in cache:
        cache[key] = Image.open(os.path.join(REPO, 'game', data['images'][key]['file'])).convert('RGBA')
    img = cache[key].crop((fr['x'], fr['y'], fr['x'] + fr['w'], fr['y'] + fr['h']))
    s = width / fr['w']
    img = img.resize((max(1, int(fr['w'] * s)), max(1, int(fr['h'] * s))), Image.LANCZOS)
    return img, fr['px'] * s, fr['py'] * s

